/* Physical-iPhone candidate: prevent automatic text inflation, without disabling page zoom. */
html{-webkit-text-size-adjust:100%;text-size-adjust:100%}
/* Touch-only game shell: HUD text and footer wrapping cannot resize the arena.
   The existing usable visual-viewport rectangle drives this grid. Desktop layout is unchanged. */
.game-active.touch-game main{display:grid;grid-template-rows:22px minmax(0,1fr) var(--game-toolbar-height,36px);gap:2px;padding-bottom:max(4px,env(safe-area-inset-bottom))}
.game-active.touch-game #brand{grid-row:1;min-height:0;overflow:hidden;align-items:center;height:22px}
.game-active.touch-game #brand h1,.game-active.touch-game #connection{white-space:nowrap}
.game-active.touch-game #notice{position:absolute;top:24px;left:15%;right:15%;z-index:8;max-height:32px;overflow:hidden;margin:0;pointer-events:none}
.game-active.touch-game #session{grid-row:2;position:relative;min-height:0;min-width:0;margin:0;padding:0;overflow:hidden}
.game-active.touch-game #game-stage{position:absolute;inset:34px 0 0;height:auto;min-height:0;grid-template-rows:minmax(0,1fr)}
.game-active.touch-game #session-code,.game-active.touch-game #outbreak-heading,.game-active.touch-game #phase-message,.game-active.touch-game #round-timer,.game-active.touch-game #healthy-count,.game-active.touch-game #live-score{position:absolute;display:block;margin:0;line-height:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-height:18px}
.game-active.touch-game #session-code{top:0;left:0;max-width:65%}
.game-active.touch-game #outbreak-heading{top:0;right:110px;max-width:20%}
.game-active.touch-game #round-timer{top:0;right:0;float:none;line-height:20px;max-height:20px}
.game-active.touch-game #phase-message{top:18px;left:0;max-width:55%}
.game-active.touch-game #healthy-count{top:18px;left:56%;max-width:22%}
.game-active.touch-game #live-score{top:18px;right:0;max-width:22%}
.game-active.touch-game #infection-feedback{position:absolute;top:38px;left:20%;right:20%;z-index:6;margin:0;pointer-events:none;text-align:center;max-height:32px;overflow:hidden}
.game-active.touch-game #session-footer{grid-row:3;min-width:0;min-height:0;height:var(--game-toolbar-height,36px);flex-wrap:wrap;align-content:flex-start;justify-content:center;overflow:hidden;white-space:nowrap;padding-bottom:0}
.game-active.touch-game #session-footer button,.game-active.touch-game #fullscreen-unavailable{flex-shrink:0}
